[BusinessEvents(classStr(MET_AXDMFImportStatusBusinessEventContract), "Data management import status business event", "Data management import status event to send the status of an import execution", ModuleAxapta::DIXF)]
public final class MET_AXDMFImportStatusBusinessEvent extends BusinessEventsBase
{
    private RefRecId recId;


}

Method.Source:
private RefRecId parmRecId(RefRecId _recId = recId)
{
    recId = _recId;
    return recId;
}

/// <summary>
/// Creates a <c>NAVAXDMFImportStatusBusinessEvent</c> from a RefRecId.
/// </summary>
/// <param name = "_recId"> The A record identifier for the <c>DMFEntityExportDetails</c> table.</param>
/// <returns>A <c>NAVAXDMFImportStatusBusinessEvent</c>.</returns>
public static MET_AXDMFImportStatusBusinessEvent newFromDMFDefinitionGroupExecutionRecId(RefRecId _recId)
{
    MET_AXDMFImportStatusBusinessEvent businessEvent = new MET_AXDMFImportStatusBusinessEvent();
    businessEvent.parmRecId(_recId);
    return businessEvent;
}

    [Wrappable(true), Replaceable(true)]
    public BusinessEventsContract buildContract()
    {
        DMFDefinitionGroupExecution dmfDefinitionGroupExecution;

        select firstonly dmfDefinitionGroupExecution
            where dmfDefinitionGroupExecution.RecId == recId;

        return MET_AXDMFImportStatusBusinessEventContract::newFromDMFDefinitionGroupExecution(dmfDefinitionGroupExecution);
    }
